import{_ as s,o as n,c as e,a6 as i}from"./chunks/framework.DL_pga9_.js";const u=JSON.parse('{"title":"Functions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/functions.md","filePath":"guide/functions.md","lastUpdated":1781686130000}'),t={name:"guide/functions.md"};function l(p,a,r,o,c,h){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h1><p>Functions are first-class citizens in NG. This chapter covers defining, calling, and composing functions.</p><h2 id="defining-functions" tabindex="-1">Defining Functions <a class="header-anchor" href="#defining-functions" aria-label="Permalink to “Defining Functions”">​</a></h2><p>Functions are defined with the <code>fun</code> keyword:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun add(x: i32, y: i32) -&gt; i32 {</span></span>
<span class="line"><span>    return x + y;</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li><code>fun</code> — keyword</li><li><code>add</code> — function name</li><li><code>(x: i32, y: i32)</code> — parameters with types</li><li><code>-&gt; i32</code> — return type</li><li><code>{ ... }</code> — function body</li></ul><h3 id="shorthand-syntax" tabindex="-1">Shorthand Syntax <a class="header-anchor" href="#shorthand-syntax" aria-label="Permalink to “Shorthand Syntax”">​</a></h3><p>Single-expression functions can use the <code>=&gt;</code> arrow:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun add(x: i32, y: i32) -&gt; i32 =&gt; x + y;</span></span></code></pre></div><h2 id="calling-functions" tabindex="-1">Calling Functions <a class="header-anchor" href="#calling-functions" aria-label="Permalink to “Calling Functions”">​</a></h2><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>val result = add(3, 4);  // 7</span></span></code></pre></div><h2 id="return-values" tabindex="-1">Return Values <a class="header-anchor" href="#return-values" aria-label="Permalink to “Return Values”">​</a></h2><p>The <code>return</code> keyword exits the function with a value. If omitted, the function returns <code>unit</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun greet(name: string) {</span></span>
<span class="line"><span>    print(&quot;Hello, &quot;, name, &quot;!&quot;);  // implicit return of unit</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The last expression in a block is <strong>not</strong> automatically returned — you must use <code>return</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun double(x: i32) -&gt; i32 {</span></span>
<span class="line"><span>    return x * 2;   // The return is required here</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h2><h3 id="required-type-annotations" tabindex="-1">Required Type Annotations <a class="header-anchor" href="#required-type-annotations" aria-label="Permalink to “Required Type Annotations”">​</a></h3><p>All parameters must have explicit type annotations:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun valid(x: i32, y: string) -&gt; bool { ... }</span></span></code></pre></div><h3 id="default-arguments" tabindex="-1">Default Arguments <a class="header-anchor" href="#default-arguments" aria-label="Permalink to “Default Arguments”">​</a></h3><p>Parameters can have default values. Defaults are evaluated at each call site and can reference earlier parameters:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun greet(greeting: string, name: string = &quot;World&quot;) -&gt; string {</span></span>
<span class="line"><span>    return greeting + &quot;, &quot; + name + &quot;!&quot;;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(greet(&quot;Hello&quot;));          // &quot;Hello, World!&quot;</span></span>
<span class="line"><span>print(greet(&quot;Hi&quot;, &quot;NG&quot;));       // &quot;Hi, NG!&quot;</span></span></code></pre></div><h2 id="recursion" tabindex="-1">Recursion <a class="header-anchor" href="#recursion" aria-label="Permalink to “Recursion”">​</a></h2><p>Functions can call themselves:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun factorial(n: i32) -&gt; i32 {</span></span>
<span class="line"><span>    if (n == 0) {</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return n * factorial(n - 1);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(factorial(5));  // 120</span></span></code></pre></div><h3 id="tail-recursion" tabindex="-1">Tail Recursion <a class="header-anchor" href="#tail-recursion" aria-label="Permalink to “Tail Recursion”">​</a></h3><p>NG optimizes tail-recursive calls. A function is tail-recursive when the recursive call is the last operation before returning:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun sum_tail(n: i32, acc: i32 = 0) -&gt; i32 {</span></span>
<span class="line"><span>    if (n == 0) {</span></span>
<span class="line"><span>        return acc;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return sum_tail(n - 1, acc + n);  // tail call</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="native-functions" tabindex="-1">Native Functions <a class="header-anchor" href="#native-functions" aria-label="Permalink to “Native Functions”">​</a></h2><p>Functions can be implemented in C++ via the <code>= native;</code> declaration:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun my_native(arg: i32) -&gt; bool = native;</span></span></code></pre></div><p>This tells the compiler that the function body is provided by the host runtime. The ORGASM VM uses <code>vm.register_native(...)</code> to bind the implementation.</p><h2 id="member-functions-methods" tabindex="-1">Member Functions (Methods) <a class="header-anchor" href="#member-functions-methods" aria-label="Permalink to “Member Functions (Methods)”">​</a></h2><p>Types can have member functions that receive <code>self</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Counter {</span></span>
<span class="line"><span>    property value: i32;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fun increment(self: ref&lt;Self&gt;, delta: i32) {</span></span>
<span class="line"><span>        self.value = self.value + delta;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    fun get(self: ref&lt;Self&gt;) -&gt; i32 {</span></span>
<span class="line"><span>        return self.value;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>val c = new Counter { value: 0 };</span></span>
<span class="line"><span>c.increment(5);</span></span>
<span class="line"><span>print(c.get());  // 5</span></span></code></pre></div><p>The <code>Self</code> type refers to the enclosing type. Methods use <code>ref&lt;Self&gt;</code> receiver parameters to allow mutation.</p><h2 id="higher-order-functions" tabindex="-1">Higher-Order Functions <a class="header-anchor" href="#higher-order-functions" aria-label="Permalink to “Higher-Order Functions”">​</a></h2><p>Functions can accept other functions as parameters. This is typically done through trait objects (see <a href="./traits">Traits</a>), but simple function references work too:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun apply_twice(f: (i32) -&gt; i32, x: i32) -&gt; i32 {</span></span>
<span class="line"><span>    return f(f(x));</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun double(x: i32) -&gt; i32 =&gt; x * 2;</span></span>
<span class="line"><span>print(apply_twice(double, 5));  // 20 (5*2*2)</span></span></code></pre></div><h2 id="function-types" tabindex="-1">Function Types <a class="header-anchor" href="#function-types" aria-label="Permalink to “Function Types”">​</a></h2><p>Function types are written as <code>(ParamType1, ParamType2) -&gt; ReturnType</code>:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type Op = (i32, i32) -&gt; i32;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fun execute(op: Op, a: i32, b: i32) -&gt; i32 {</span></span>
<span class="line"><span>    return op(a, b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="overloading" tabindex="-1">Overloading <a class="header-anchor" href="#overloading" aria-label="Permalink to “Overloading”">​</a></h2><p>Multiple functions can share the same name if they have different parameter types. The type checker selects the best match through overload resolution:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fun print_value(x: i32) { print(&quot;int:&quot;, x); }</span></span>
<span class="line"><span>fun print_value(x: string) { print(&quot;string:&quot;, x); }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print_value(42);       // calls first overload</span></span>
<span class="line"><span>print_value(&quot;hello&quot;);  // calls second overload</span></span></code></pre></div><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to “What&#39;s Next?”">​</a></h2><p>Continue to <a href="./data-structures">Data Structures</a> to learn about arrays, tuples, objects, and tagged unions.</p><blockquote><p><strong>Try it:</strong> <code>example/03.funcall_and_idexpr.ng</code> — Function calls and index expressions <strong>Try it:</strong> <code>example/09.scope.ng</code> — Scope and closures</p></blockquote>`,49)])])}const g=s(t,[["render",l]]);export{u as __pageData,g as default};
